import 'package:flutter/material.dart'; import '../data/database.dart'; import '../models/models.dart';
const sections=['DM Templates','Editing Checklist','Client Onboarding','Other'];
class LibraryScreen extends StatefulWidget{const LibraryScreen({super.key});@override State<LibraryScreen> createState()=>_S();}class _S extends State<LibraryScreen>{final db=AppDb.instance;List<LibraryItem> items=[];Set<int> open={};@override void initState(){super.initState();load();}Future<void>load()async{final x=await db.library();if(mounted)setState(()=>items=x);}Future<void>form([LibraryItem? old])async{final title=TextEditingController(text:old?.title),content=TextEditingController(text:old?.content);String section=old?.section??sections.first;await showDialog(context:context,builder:(ctx)=>AlertDialog(title:Text(old==null?'Add library item':'Edit item'),content:SingleChildScrollView(child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),DropdownButtonFormField(initialValue:section,items:sections.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>section=v!,decoration:const InputDecoration(labelText:'Section')),TextField(controller:content,maxLines:10,decoration:const InputDecoration(labelText:'Content'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()async{await db.saveLibrary(LibraryItem(id:old?.id,title:title.text.trim(),section:section,content:content.text));if(ctx.mounted)Navigator.pop(ctx);load();},child:const Text('Save'))]));}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('SOP / Script Library'),actions:[IconButton(onPressed:()=>form(),icon:const Icon(Icons.add))]),body:items.isEmpty?const Center(child:Text('No reusable content yet. Tap + to add.')):ListView(padding:const EdgeInsets.all(12),children:sections.map((sec){final xs=items.where((x)=>x.section==sec).toList();if(xs.isEmpty)return const SizedBox.shrink();return Card(child:ExpansionTile(title:Text(sec),children:xs.map((x)=>ExpansionTile(title:Text(x.title),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,8),child:Align(alignment:Alignment.centerLeft,child:SelectableText(x.content))),Row(mainAxisAlignment:MainAxisAlignment.end,children:[IconButton(onPressed:()=>form(x),icon:const Icon(Icons.edit)),IconButton(onPressed:()async{await db.deleteLibrary(x.id!);load();},icon:const Icon(Icons.delete_outline))])])).toList()));}).toList()));}